func TestEchoConnCancelDuringBlockedEcho(t *testing.T) {
	api := newFakeEchoAPI()
	c := mustOpen(t, newEchoProber(api), 5)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	sentAt, _ := c.send()

